using System.Collections.Generic;
using System.ComponentModel;
using System.Runtime.CompilerServices;

namespace PZWorkshopDownloader.Models;

public class ModRecord : INotifyPropertyChanged
{
    public string Folder { get; set; } = "";
    public string FullPath { get; set; } = "";
    public string Id { get; set; } = "";
    public string ModName { get; set; } = "";

    // Used on the Updater tab
    public string LocalVersion { get; set; } = "";
    public string SteamVersion { get; set; } = "";
    public string DownloadSize { get; set; } = "";
    public bool NeedsUpdate { get; set; }
    public string StatusLabel { get; set; } = "Updated";
    public string Creator { get; set; } = "";

    // ================= Items 1-3: Dependency handling =================
    // Dependency identifiers parsed from this mod's require= field of mod.info
    // (numeric workshop IDs and/or internal mod names like "NeatUI_Framework").
    public List<string> Dependencies { get; set; } = new();

    // The subset of Dependencies that could NOT be matched to an installed mod
    // under the user's mods folder. Drives the "Show Deps" dialog (missing
    // numeric entries can be queued; name-only entries open Steam search).
    public List<string> MissingDependencies { get; set; } = new();

    // Count of dependencies that do not have a corresponding installed folder under the user's mods folder.
    public int MissingDepsCount { get; set; }

    // Used by the Requirements status column (green "Met" / pulsing orange "Missing").
    public bool HasMissingDeps => MissingDepsCount > 0;

    public bool HasDependencies => Dependencies.Count > 0;

    public string RequirementLabel => Dependencies.Count == 0
        ? "No Requirements"
        : MissingDepsCount == 0 ? "Requirements Met" : $"{MissingDepsCount} missing";

    // Used on the Downloader tab
    public string Size { get; set; } = "";
    public string Posted { get; set; } = "";
    public string Updated { get; set; } = "";
    public string InstallDate { get; set; } = "";

    // ================= Batch 4: visual subsystem =================
    // Path to the locally cached thumbnail (set asynchronously after the grid
    // is populated, hence INPC). Empty until the fetch/download completes.
    private string _thumbnailPath = "";
    public string ThumbnailPath
    {
        get => _thumbnailPath;
        set { if (_thumbnailPath != value) { _thumbnailPath = value; OnPropertyChanged(); } }
    }

    // Steam workshop tags for this mod (e.g. "Map", "Survivor", ...) used by
    // the tag filter sidebar. Populated by the same visual fetch as the thumbnail.
    public List<string> Tags { get; set; } = new();

    // Comma-separated tag string for the Tags grid column.
    public string TagsLabel => Tags.Count == 0 ? "" : string.Join(", ", Tags);

    // First character of the display name — the placeholder shown until the
    // thumbnail arrives (or forever, for mods without a preview image).
    public string Initial => ModName.Length > 0 ? ModName[..1].ToUpperInvariant() : "?";

    public event PropertyChangedEventHandler? PropertyChanged;

    protected void OnPropertyChanged([CallerMemberName] string? name = null) =>
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(name));
}

