namespace PZWorkshopDownloader.Services;

/// <summary>
/// Local thumbnail cache. Thumbnails are stored as "&lt;workshopId&gt;.jpg"
/// under %LOCALAPPDATA%\PZWorkshopDownloader\thumbnails\ and are reused across
/// runs, so only genuinely missing images get re-downloaded.
/// </summary>
public static class ThumbnailStore
{
    private static readonly HttpClient Http = new();

    public static string CacheDir => Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
        "PZWorkshopDownloader", "thumbnails");

    /// <summary>Path to the cached thumbnail for a workshop id, or "" if not cached.</summary>
    public static string GetCachedPath(string workshopId)
    {
        if (string.IsNullOrEmpty(workshopId)) return "";
        var path = Path.Combine(CacheDir, workshopId + ".jpg");
        return File.Exists(path) ? path : "";
    }

    /// <summary>
    /// Downloads a thumbnail into the cache. Returns the local path on success,
    /// or "" if the download failed (callers then fall back to a placeholder).
    /// Never throws.
    /// </summary>
    public static async Task<string> DownloadAsync(string workshopId, string previewUrl)
    {
        if (string.IsNullOrEmpty(workshopId) || string.IsNullOrEmpty(previewUrl)) return "";
        try
        {
            Directory.CreateDirectory(CacheDir);
            var bytes = await Http.GetByteArrayAsync(previewUrl);
            if (bytes.Length == 0) return "";
            var path = Path.Combine(CacheDir, workshopId + ".jpg");
            await File.WriteAllBytesAsync(path, bytes);
            return path;
        }
        catch
        {
            return "";
        }
    }

    /// <summary>Cache path if already present, otherwise downloads and returns it (or "" on failure).</summary>
    public static async Task<string> GetOrDownloadAsync(string workshopId, string previewUrl)
    {
        var cached = GetCachedPath(workshopId);
        if (cached.Length > 0) return cached;
        return await DownloadAsync(workshopId, previewUrl);
    }
}

