namespace PZWorkshopDownloader;

public partial class MainWindow : Window
{
    private const string WorkshopHomeUrl =
        "https://steamcommunity.com/workshop/browse/?appid=" + SteamCmdService.AppId +
        "&browsesort=trend&section=readytouseitems";

    private readonly AppSettings _settings;
    private readonly ObservableCollection<QueueItem> _queue = new();
    private readonly ObservableCollection<ModRecord> _downloadedMods = new();
    private readonly ObservableCollection<DownloadTask> _downloads = new();
    private readonly ObservableCollection<UninstalledModEntry> _uninstalledMods = new();

    // Per-session cache of "Show Deps" Workshop-page lookups (workshopId ->
    // parsed required items), so re-opening the popup for the same mod doesn't
    // re-download the page. The in-flight set prevents duplicate simultaneous
    // fetches if the button is clicked repeatedly.
    private readonly Dictionary<string, List<WorkshopRequiredItem>> _depsPageCache = new();
    private readonly HashSet<string> _depsFetchInFlight = new();

    // ================= Batch 4: visual subsystem =================
    // Currently selected tag filters for the Installed Mods sidebar.
    private readonly HashSet<string> _selectedTags = new(StringComparer.OrdinalIgnoreCase);

    // Guards the thumbnail download fan-out so a large mod list doesn't
    // hammer the CDN with hundreds of concurrent requests.
    private static readonly SemaphoreSlim ThumbnailGate = new(4);

    private bool _tagSidebarExpanded = true;

    public MainWindow()
    {
        InitializeComponent();

        _settings = SettingsService.Load();

        QueueList.ItemsSource = _queue;
        _queue.CollectionChanged += (_, _) => UpdateQueuePanelVisibility();
        UpdateQueuePanelVisibility();
        DownloadedModsGrid.ItemsSource = _downloadedMods;
        foreach (var e in DownloadHistoryStore.Load())
        {
            _downloads.Add(new DownloadTask
            {
                Id = e.Id,
                Title = e.Title,
                Status = e.Status,
                Detail = e.Detail,
                StartedAt = e.StartedAt,
                FinishedAt = e.FinishedAt,
            });
        }
        DownloadsGrid.ItemsSource = _downloads;

        foreach (var entry in UninstalledModsStore.Load()) _uninstalledMods.Add(entry);
        UninstalledModsGrid.ItemsSource = _uninstalledMods;

        LogList.ItemsSource = _logEntries;

        // Batch 4: default tile size and shared views. Tiles bind to the same
        // collections as the grids, so the tag filter applies to both.
        Application.Current.Resources["ModTileSize"] = 140d;
        InstalledTiles.ItemsSource = _downloadedMods;
        DownloadsTiles.ItemsSource = _downloads;
        UninstalledTiles.ItemsSource = _uninstalledMods;

        // Fetch previews/tags + thumbnails for history and uninstalled lists
        // in the background; the grid/tile placeholders fill in as they arrive.
        _ = LoadDownloadsThumbnailsAsync();
        _ = LoadUninstalledThumbnailsAsync();

        PzFolderBox.Text = _settings.ModsFolder;
        DestFolderLabel.Text = string.IsNullOrWhiteSpace(_settings.ModsFolder) ? "Not set" : _settings.ModsFolder;
        BackupCheckbox.IsChecked = _settings.BackupUpdatedMods;
        AutoRefreshCheckbox.IsChecked = _settings.AutoRefreshOnTabSwitch;
        DebugLoggingCheckbox.IsChecked = _settings.DebugLogging;
        ThemeCombo.SelectedIndex = _settings.Theme switch
        {
            "Light" => 0,
            "Dark" => 1,
            "Midnight" => 2,
            "Forest" => 3,
            "Nord" => 4,
            "Dracula" => 5,
            "Solarized Dark" => 6,
            "Solarized Light" => 7,
            "Gruvbox" => 8,
            "Monokai" => 9,
            _ => 1,
        };
        ApplyTheme(_settings.Theme);

        ApplyUiFontSizes();

        Browser.SourceChanged += (_, _) => AddressBar.Text = Browser.Source?.ToString() ?? "";
        MainTabs.SelectionChanged += MainTabs_SelectionChanged;

        Loaded += MainWindow_Loaded;
    }

    private void MainTabs_SelectionChanged(object sender, System.Windows.Controls.SelectionChangedEventArgs e)
    {
        if (_settings.AutoRefreshOnTabSwitch && MainTabs.SelectedItem == InstalledModsTabItem)
            _ = RefreshDownloadedModsAsync();
    }

    private async void MainWindow_Loaded(object sender, RoutedEventArgs e)
    {
        AppendLog("Application started.");
        try
        {
            await Browser.EnsureCoreWebView2Async();
        }
        catch (Exception ex)
        {
            MessageBox.Show(
                "Could not start the embedded browser (WebView2). Make sure the " +
                "WebView2 Runtime is installed.\n\n" + ex.Message,
                "Browser init failed", MessageBoxButton.OK, MessageBoxImage.Warning);
            AppendLog($"Browser init failed: {ex.Message}");
        }

        await RefreshDownloadedModsAsync();
    }

    // ================= Bottom log panel =================

    private readonly ObservableCollection<LogEntry> _logEntries = new();
    private bool _logExpanded = false;

    private void ToggleLog_Click(object sender, RoutedEventArgs e)
    {
        _logExpanded = !_logExpanded;
        LogToggle.Content = _logExpanded ? "Hide Log \u25BC" : "Show Log \u25B2";

        var anim = new DoubleAnimation
        {
            To = _logExpanded ? 260 : 0,
            Duration = TimeSpan.FromMilliseconds(220),
            EasingFunction = new QuadraticEase { EasingMode = EasingMode.EaseInOut },
        };
        LogPanelBorder.BeginAnimation(HeightProperty, anim);
    }

    private void ClearLogButton_Click(object sender, RoutedEventArgs e)
    {
        _logEntries.Clear();
        JumpToBottomButton.Visibility = Visibility.Collapsed;
    }

    private void JumpToBottomButton_Click(object sender, RoutedEventArgs e)
    {
        if (_logEntries.Count > 0) LogList.ScrollIntoView(_logEntries[_logEntries.Count - 1]);
        JumpToBottomButton.Visibility = Visibility.Collapsed;
    }

    private bool IsLogAtBottom()
    {
        var sv = FindScrollViewer(LogList);
        if (sv == null) return true; // not rendered yet -- default to following
        return sv.ScrollableHeight <= 0 || sv.VerticalOffset >= sv.ScrollableHeight - 4;
    }

    private static ScrollViewer? FindScrollViewer(DependencyObject d)
    {
        for (int i = 0; i < VisualTreeHelper.GetChildrenCount(d); i++)
        {
            var child = VisualTreeHelper.GetChild(d, i);
            if (child is ScrollViewer sv) return sv;
            var result = FindScrollViewer(child);
            if (result != null) return result;
        }
        return null;
    }

    /// <summary>
    /// Appends a timestamped line to the in-app log panel so backend
    /// activity is visible without digging through any log file. Safe to
    /// call from any thread. DEBUG-level lines (raw, high-volume SteamCMD
    /// output) are skipped unless the debug logging setting is on. Only
    /// auto-scrolls if the user was already at the bottom -- otherwise a
    /// "Jump to Bottom" button appears instead of yanking their view.
    /// </summary>
    private void AppendLog(string message, string level = "INFO")
    {
        if (level == "DEBUG" && !_settings.DebugLogging) return;

        void Do()
        {
            bool wasAtBottom = IsLogAtBottom();

            _logEntries.Add(new LogEntry
            {
                Time = DateTime.Now.ToString("HH:mm:ss"),
                Level = level,
                Message = message,
            });
            while (_logEntries.Count > 500) _logEntries.RemoveAt(0);

            if (wasAtBottom)
            {
                LogList.UpdateLayout();
                if (_logEntries.Count > 0) LogList.ScrollIntoView(_logEntries[_logEntries.Count - 1]);
                JumpToBottomButton.Visibility = Visibility.Collapsed;
            }
            else
            {
                JumpToBottomButton.Visibility = Visibility.Visible;
            }
        }

        if (Dispatcher.CheckAccess()) Do();
        else Dispatcher.Invoke(Do);
    }

