    /// <summary>Returns true on success.</summary>
    private async Task<bool> StartDownloadAsync(string id, string title, bool showFolderWarning = true)
    {
        if (string.IsNullOrWhiteSpace(_settings.ModsFolder))
        {
            if (showFolderWarning) MessageBox.Show("Choose a destination folder first.");
            return false;
        }

        var task = new DownloadTask
        {
            Id = id,
            Title = title,
            Status = "Downloading",
            StartedAt = DateTime.Now.ToString("h:mm:ss tt"),
        };
        _downloads.Insert(0, task);
        SaveDownloadHistory();

        // Batch 4: fetch this mod's preview thumbnail in the background so the
        // Downloads tab shows it even before a full history reload.
        _ = FetchTaskThumbnailAsync(task);

        StatusText.Text = $"Downloading {title}...";
        AppendLog($"Starting download: {title} ({id})");
        ProgressBarCtl.IsIndeterminate = true;
        try
        {
            var installedPaths = await SteamCmdService.DownloadModAsync(id, _settings.ModsFolder, line =>
            {
                // SteamCMD's output arrives on a background thread.
                Dispatcher.Invoke(() => task.Detail = line);
                AppendLog(line, "DEBUG");
            });

            // Record the content manifest id (not a date) as the "version"
            // we now have locally, so future update-checks compare like for like.
            try
            {
                var details = await WorkshopApiService.GetDetailsAsync(id);
                _settings.LocalModVersions[id] = details.ContentManifestId;
                _settings.InstallDates[id] = DateTimeOffset.Now.ToString("dd-MMM-yy h:mm:ss tt");
            }
            catch
            {
                // Offline right after downloading -- leave whatever version
                // was previously recorded (or none) rather than fail the download.
            }
            SettingsService.Save(_settings);

            task.Status = "Done";
            task.FinishedAt = DateTime.Now.ToString("h:mm:ss tt");
            task.Detail = installedPaths.Count == 1
                ? $"Installed to \"{Path.GetFileName(installedPaths[0])}\""
                : $"{installedPaths.Count} mod folders installed";

            StatusText.Text = installedPaths.Count == 1
                ? $"Done: {title}"
                : $"Done: {title} ({installedPaths.Count} mod folders installed)";
            AppendLog($"Finished: {title} \u2714 ({installedPaths.Count} folder(s))");
            SaveDownloadHistory();
            await RefreshDownloadedModsAsync();
            return true;
        }
        catch (Exception ex)
        {
            task.Status = "Failed";
            task.FinishedAt = DateTime.Now.ToString("h:mm:ss tt");
            task.Detail = ex.Message;
            StatusText.Text = $"Failed: {title} — {ex.Message}";
            AppendLog($"FAILED: {title} — {ex.Message}", "ERROR");
            SaveDownloadHistory();
            return false;
        }
        finally
        {
            ProgressBarCtl.IsIndeterminate = false;
        }
    }

