    /// <summary>
    /// Figures out which Steam Workshop id a local mod folder corresponds to.
    /// Tries the "&lt;id&gt; &lt;name&gt;" naming convention this app installs mods
    /// under first, then falls back to scanning any mod.info file inside for
    /// a purely-numeric id= line (some mods happen to use one).
    /// </summary>
    private static bool TryExtractWorkshopId(string folderPath, out string id)
    {
        id = "";
        var name = Path.GetFileName(folderPath);
        if (name.StartsWith("_")) return false; // skip internal folders like _backups

        var m = Regex.Match(name, @"^(\d+)");
        if (m.Success)
        {
            id = m.Groups[1].Value;
            return true;
        }

        try
        {
            foreach (var infoFile in Directory.EnumerateFiles(folderPath, "mod.info", SearchOption.AllDirectories))
            {
                foreach (var line in File.ReadAllLines(infoFile))
                {
                    var lm = Regex.Match(line.Trim(), @"^id\s*=\s*(\d+)\s*$", RegexOptions.IgnoreCase);
                    if (lm.Success)
                    {
                        id = lm.Groups[1].Value;
                        return true;
                    }
                }
            }
        }
        catch
        {
            // Unreadable folder -- treat as unresolvable.
        }

        return false;
    }

    /// <summary>
    /// Normalizes a mod identifier for dependency matching: lowercase, remove
    /// spaces and punctuation, so "NeatUI_Framework" == "neatui framework" ==
    /// "NeatUI Framework" when comparing require= values against installed
    /// mods' id=/name= fields.
    /// </summary>
    private static string NormalizeModIdentifier(string value)
    {
        var sb = new System.Text.StringBuilder(value.Length);
        foreach (var c in value)
        {
            if (char.IsLetterOrDigit(c)) sb.Append(char.ToLowerInvariant(c));
        }
        return sb.ToString();
    }

