    private void ExportModList_Click(object sender, RoutedEventArgs e)
    {
        if (_downloadedMods.Count == 0)
        {
            MessageBox.Show("No installed mods to export yet. Try 'Refresh Mod List' first.");
            return;
        }

        var dlg = new Microsoft.Win32.SaveFileDialog
        {
            Filter = "XML files (*.xml)|*.xml",
            FileName = "pz_mod_list.xml",
        };
        if (dlg.ShowDialog() != true) return;

        try
        {
            var root = new XElement("ModList",
                _downloadedMods.Select(m => new XElement("Mod",
                    new XElement("Name", m.ModName),
                    new XElement("WorkshopID", m.Id),
                    new XElement("Author", m.Creator),
                    new XElement("Link", $"https://steamcommunity.com/sharedfiles/filedetails/?id={m.Id}"))));
            new XDocument(root).Save(dlg.FileName);

            AppendLog($"Exported {_downloadedMods.Count} mod(s) to {dlg.FileName}");
            StatusText.Text = "Mod list exported.";
        }
        catch (Exception ex)
        {
            MessageBox.Show($"Could not save file: {ex.Message}");
            AppendLog($"Export failed: {ex.Message}", "ERROR");
        }
    }

    private void ImportModList_Click(object sender, RoutedEventArgs e)
    {
        var dlg = new Microsoft.Win32.OpenFileDialog { Filter = "XML files (*.xml)|*.xml" };
        if (dlg.ShowDialog() != true) return;

        XDocument doc;
        try
        {
            doc = XDocument.Load(dlg.FileName);
        }
        catch (Exception ex)
        {
            MessageBox.Show($"Could not read XML file: {ex.Message}");
            AppendLog($"Import failed: {ex.Message}", "ERROR");
            return;
        }

        var installedIds = _downloadedMods.Select(m => m.Id).ToHashSet();
        int added = 0, skipped = 0;

        foreach (var modEl in doc.Root?.Elements("Mod") ?? Enumerable.Empty<XElement>())
        {
            var id = modEl.Element("WorkshopID")?.Value?.Trim();
            var name = modEl.Element("Name")?.Value?.Trim();
            if (string.IsNullOrEmpty(id)) continue;

            if (installedIds.Contains(id) || _queue.Any(q => q.Id == id))
            {
                skipped++;
                continue;
            }

            _queue.Add(new QueueItem { Id = id, Title = string.IsNullOrEmpty(name) ? id : name, Status = "Queued" });
            added++;
        }

        AppendLog($"Imported mod list from {dlg.FileName}: {added} added to queue, {skipped} skipped (already installed or queued).");
        MessageBox.Show(
            $"{added} mod(s) added to the download queue.\n{skipped} were already installed or queued and skipped.\n\n" +
            "Switch to the Browser tab and click 'Start Downloading All' in the queue panel to fetch them.",
            "Import Complete");
    }

    /// <summary>
    /// Scans the mods folder, pulls live details from Steam for each mod,
    /// and determines which ones need an update -- this single pass now
    /// covers both "list what's installed" and "check for updates" (the
    /// tabs used to be separate; merged so there's one source of truth).
    /// </summary>
    private async Task RefreshDownloadedModsAsync()
    {
        if (string.IsNullOrWhiteSpace(_settings.ModsFolder) || !Directory.Exists(_settings.ModsFolder))
            return;

        AppendLog("Refreshing mod list and checking for updates...");
        var records = new List<ModRecord>();
        int updatesAvailable = 0;

        // Build an index of every installed mod's declared identifiers (id=/name=
        // from its mod.info) -> real workshop id (the numeric folder prefix), plus
        // the set of installed workshop ids. This lets require= entries (numeric
        // ids or internal names like "\NeatUI_Framework") be resolved purely
        // against what is already on disk -- no extra Steam API calls.
        var installedWorkshopIds = new HashSet<string>(StringComparer.Ordinal);
        var identifierIndex = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (var dir in Directory.GetDirectories(_settings.ModsFolder))
        {
            if (!TryExtractWorkshopId(dir, out var knownId)) continue;
            installedWorkshopIds.Add(knownId);
            foreach (var ident in SteamCmdService.GetModIdentifiers(dir))
            {
                var key = NormalizeModIdentifier(ident);
                if (key.Length > 0) identifierIndex.TryAdd(key, knownId);
            }
        }

        foreach (var dir in Directory.GetDirectories(_settings.ModsFolder))
        {
            if (!TryExtractWorkshopId(dir, out var id)) continue;
            var folderName = Path.GetFileName(dir);

            // Resolve require= entries against the installed-mod index above.
            var requires = SteamCmdService.GetRequiresFields(dir);
            var missingDeps = new List<string>();
            foreach (var req in requires)
            {
                bool met = long.TryParse(req, out _)
                    ? installedWorkshopIds.Contains(req)
                    : identifierIndex.TryGetValue(NormalizeModIdentifier(req), out _);
                if (!met) missingDeps.Add(req);
            }

            string title = folderName, posted = "", updated = "", steamVer = "Unknown", creator = "";
            bool resolvedRemote = false;
            try
            {
                var details = await WorkshopApiService.GetDetailsAsync(id);
                title = details.Title;
                posted = details.TimeCreated == default ? "" : details.TimeCreated.ToLocalTime().ToString("dd-MMM-yy h:mm:ss tt");
                updated = details.TimeUpdated == default ? "" : details.TimeUpdated.ToLocalTime().ToString("dd-MMM-yy h:mm:ss tt");
                steamVer = string.IsNullOrEmpty(details.ContentManifestId) ? "Unknown" : details.ContentManifestId;
                resolvedRemote = !string.IsNullOrEmpty(details.ContentManifestId);
                creator = details.Creator;
            }
            catch
            {
                // Offline, or the item was removed -- still show the folder by id.
            }

            var hasLocalVersion = _settings.LocalModVersions.TryGetValue(id, out var lv) && !string.IsNullOrEmpty(lv);
            var localVer = hasLocalVersion ? lv! : "Unknown";
            var installDate = _settings.InstallDates.TryGetValue(id, out var idate) ? idate : "";

            bool needsUpdate;
            if (!resolvedRemote)
                needsUpdate = false; // couldn't reach Steam -- don't false-flag
            else if (!hasLocalVersion)
                needsUpdate = true; // never tracked (e.g. placed manually) -- flag so the user can decide
            else
                needsUpdate = !string.Equals(lv, steamVer, StringComparison.Ordinal);

            if (needsUpdate) updatesAvailable++;

            records.Add(new ModRecord
            {
                Folder = folderName,
                FullPath = dir,
                Id = id,
                ModName = title,
                Size = FormatSize(GetDirectorySize(dir)),
                Posted = posted,
                Updated = updated,
                LocalVersion = localVer,
                SteamVersion = steamVer,
                InstallDate = installDate,
                NeedsUpdate = needsUpdate,
                StatusLabel = needsUpdate ? "Update Available" : "Updated",
                Creator = creator,
                Dependencies = requires,
                MissingDependencies = missingDeps,
                MissingDepsCount = missingDeps.Count,
            });
        }

        _downloadedMods.Clear();
        foreach (var r in records) _downloadedMods.Add(r);

        UpdatesAvailableText.Text = $"Mods with updates available: {updatesAvailable}";
        UpdateAllButton.IsEnabled = updatesAvailable > 0;
        AppendLog($"Refresh complete: {records.Count} mod(s) installed, {updatesAvailable} update(s) available.");

        // Batch 4: kick off the preview/tag/thumbnail fetch for installed mods
        // in the background. Tag sidebar + thumbnails fill in as it completes.
        _ = LoadInstalledVisualsAsync();
    }

    // ================= Batch 4: visual loading pipeline =================

    /// <summary>
    /// Fetches preview_url + tags for the installed mods in one batched API
    /// call, downloads any missing thumbnails into the cache (throttled), then
    /// rebuilds the tag sidebar. Runs in the background; grids/tiles update in
    /// place because ThumbnailPath raises PropertyChanged.
    /// </summary>
    private async Task LoadInstalledVisualsAsync()
    {
        try
        {
            var mods = _downloadedMods.ToList();
            if (mods.Count == 0) { RebuildTagSidebar(); return; }

            var visuals = await WorkshopVisualService.GetVisualsAsync(mods.Select(m => m.Id));

            await Task.WhenAll(mods.Select(async m =>
            {
                if (!visuals.TryGetValue(m.Id, out var v)) return;
                m.Tags = v.Tags;
                await ThumbnailGate.WaitAsync();
                try
                {
                    m.ThumbnailPath = await ThumbnailStore.GetOrDownloadAsync(m.Id, v.PreviewUrl);
                }
                finally
                {
                    ThumbnailGate.Release();
                }
            }));

            await Dispatcher.InvokeAsync(RebuildTagSidebar);
            AppendLog($"Loaded previews/tags for {mods.Count} installed mod(s).");
        }
        catch (Exception ex)
        {
            AppendLog($"Could not load mod visuals: {ex.Message}", "WARNING");
        }
    }

    private async Task LoadDownloadsThumbnailsAsync()
    {
        try
        {
            var tasks = _downloads.Where(t => !string.IsNullOrEmpty(t.Id)).Select(t => t.Id).Distinct().ToList();
            if (tasks.Count == 0) return;
            var visuals = await WorkshopVisualService.GetVisualsAsync(tasks);

            await Task.WhenAll(_downloads.Select(async t =>
            {
                if (!visuals.TryGetValue(t.Id, out var v)) return;
                await ThumbnailGate.WaitAsync();
                try
                {
                    t.ThumbnailPath = await ThumbnailStore.GetOrDownloadAsync(t.Id, v.PreviewUrl);
                }
                finally
                {
                    ThumbnailGate.Release();
                }
            }));
        }
        catch (Exception ex)
        {
            AppendLog($"Could not load download thumbnails: {ex.Message}", "WARNING");
        }
    }

    /// <summary>
    /// Fetches a single download task's preview thumbnail (used right after a
    /// new download starts). Never throws.
    /// </summary>
    private async Task FetchTaskThumbnailAsync(DownloadTask task)
    {
        try
        {
            if (string.IsNullOrEmpty(task.Id)) return;
            var visuals = await WorkshopVisualService.GetVisualsAsync(new[] { task.Id });
            if (!visuals.TryGetValue(task.Id, out var v)) return;
            task.ThumbnailPath = await ThumbnailStore.GetOrDownloadAsync(task.Id, v.PreviewUrl);
        }
        catch
        {
            // Thumbnails are cosmetic; a failure here must never disturb a download.
        }
    }

    private async Task LoadUninstalledThumbnailsAsync()
    {
        try
        {
            var entries = _uninstalledMods.ToList();
            if (entries.Count == 0) return;
            var visuals = await WorkshopVisualService.GetVisualsAsync(entries.Select(e => e.Id));

            await Task.WhenAll(entries.Select(async e =>
            {
                if (!visuals.TryGetValue(e.Id, out var v)) return;
                await ThumbnailGate.WaitAsync();
                try
                {
                    e.ThumbnailPath = await ThumbnailStore.GetOrDownloadAsync(e.Id, v.PreviewUrl);
                }
                finally
                {
                    ThumbnailGate.Release();
                }
            }));
        }
        catch (Exception ex)
        {
            AppendLog($"Could not load uninstalled-mod thumbnails: {ex.Message}", "WARNING");
        }
    }

    // ================= Batch 4: tag filter sidebar =================

    /// <summary>
    /// Rebuilds the Installed Mods tag sidebar from the union of Steam tags
    /// across installed mods, preserving whatever filters were already checked.
    /// </summary>
    private void RebuildTagSidebar()
    {
        var tags = _downloadedMods.SelectMany(m => m.Tags)
            .Where(t => !string.IsNullOrWhiteSpace(t))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(t => t, StringComparer.OrdinalIgnoreCase)
            .ToList();

        var kept = _selectedTags.Where(t => tags.Contains(t, StringComparer.OrdinalIgnoreCase)).ToList();

        TagFilterPanel.Children.Clear();
        foreach (var tag in tags)
        {
            var cb = new CheckBox
            {
                Content = tag,
                Tag = tag,
                IsChecked = kept.Contains(tag, StringComparer.OrdinalIgnoreCase),
                Margin = new Thickness(0, 2, 0, 2),
            };
            cb.SetResourceReference(Control.ForegroundProperty, "FgText");
            cb.Checked += TagFilter_Changed;
            cb.Unchecked += TagFilter_Changed;
            TagFilterPanel.Children.Add(cb);
        }

        TagCountText.Text = $"{tags.Count} tag(s)";
        _selectedTags.Clear();
        foreach (var t in kept) _selectedTags.Add(t);
        ApplyInstalledTagFilter();
    }

    private void TagFilter_Changed(object? sender, RoutedEventArgs e)
    {
        if (sender is not CheckBox { Tag: string tag } cb) return;
        if (cb.IsChecked == true) _selectedTags.Add(tag);
        else _selectedTags.Remove(tag);
        ApplyInstalledTagFilter();
    }

    /// <summary>
    /// Filters the installed-mod collection through the shared collection view
    /// so the list grid AND the tile view update together. A mod is shown when
    /// no filters are selected, or when it matches any selected tag. Mods with
    /// no tag data stay visible so nothing gets hidden by accident.
    /// </summary>
    private void ApplyInstalledTagFilter()
    {
        var view = CollectionViewSource.GetDefaultView(_downloadedMods);
        view.Filter = _selectedTags.Count == 0 ? null :
            o => o is ModRecord m && (m.Tags.Count == 0 || m.Tags.Any(t => _selectedTags.Contains(t)));
    }

