    private void ThemeCombo_SelectionChanged(object sender, System.Windows.Controls.SelectionChangedEventArgs e)
    {
        if (!IsLoaded) return;
        if (ThemeCombo.SelectedItem is not System.Windows.Controls.ComboBoxItem item) return;

        var themeName = item.Content?.ToString() ?? "Dark";
        _settings.Theme = themeName;
        SettingsService.Save(_settings);
        ApplyTheme(themeName);
        AppendLog($"Theme changed to: {themeName}");
    }

    private static void ApplyTheme(string theme)
    {
        // (BgDark, BgPanel, BgField, FgText, AccentBlue, AccentGreen, BorderCol)
        var palette = theme switch
        {
            // The original light theme.
            "Light" => ("#F0F0F0", "#E0E0E0", "#FFFFFF", "#202020", "#2E7BD6", "#3E8E41", "#C0C0C0"),
            // The original Steam-styled dark theme.
            "Dark" => ("#1B2838", "#171A21", "#2A2F35", "#C7D5E0", "#66C0F4", "#5C7E10", "#3A3F44"),
            // Deep indigo/violet with a soft teal-green accent.
            "Midnight" => ("#14121F", "#1E1B2E", "#2A2540", "#D8D3F0", "#9D7CF0", "#4CD9A0", "#3D3660"),
            // Dark forest green with warm lime accent.
            "Forest" => ("#101C14", "#16261B", "#1F3327", "#D4E8D8", "#5FB0A6", "#8BC34A", "#2E4A38"),
            // Nord (arctic, bluish-gray palette by Sven Greb -- nordtheme.com)
            "Nord" => ("#2E3440", "#3B4252", "#434C5E", "#ECEFF4", "#88C0D0", "#A3BE8C", "#4C566A"),
            // Dracula (dracula theme -- draculatheme.com)
            "Dracula" => ("#282A36", "#21222C", "#44475A", "#F8F8F2", "#8BE9FD", "#50FA7B", "#6272A4"),
            // Solarized Dark (Ethan Schoonover -- ethanschoonover.com/solarized)
            "Solarized Dark" => ("#002B36", "#073642", "#0A4552", "#93A1A1", "#268BD2", "#859900", "#586E75"),
            // Solarized Light (same palette, light variant)
            "Solarized Light" => ("#FDF6E3", "#EEE8D5", "#FFFFFF", "#586E75", "#268BD2", "#859900", "#93A1A1"),
            // Gruvbox (retro groove palette by morhetz)
            "Gruvbox" => ("#282828", "#3C3836", "#504945", "#EBDBB2", "#83A598", "#B8BB26", "#665C54"),
            // Monokai (classic Sublime Text scheme)
            "Monokai" => ("#272822", "#1E1F1C", "#3E3D32", "#F8F8F2", "#66D9EF", "#A6E22E", "#75715E"),
            _ => ("#1B2838", "#171A21", "#2A2F35", "#C7D5E0", "#66C0F4", "#5C7E10", "#3A3F44"),
        };

        try
        {
            var res = Application.Current.Resources;
            SetBrush(res, "BgDark", palette.Item1);
            SetBrush(res, "BgPanel", palette.Item2);
            SetBrush(res, "BgField", palette.Item3);
            SetBrush(res, "FgText", palette.Item4);
            SetBrush(res, "AccentBlue", palette.Item5);
            SetBrush(res, "AccentGreen", palette.Item6);
            SetBrush(res, "BorderCol", palette.Item7);
        }
        catch
        {
            // Theming is cosmetic -- never let it take the app down.
        }
    }

    private static void SetBrush(ResourceDictionary res, string key, string hex)
    {
        // Replace the resource entirely (rather than mutating the existing
        // brush's Color) -- WPF freezes Freezable resources declared purely
        // in XAML for performance, which silently blocks in-place mutation.
        // DynamicResource consumers pick up a replaced entry immediately.
        res[key] = new SolidColorBrush((Color)ColorConverter.ConvertFromString(hex));
    }
}

