```csharp
    /// <summary>
    /// Deletes the contents of the SteamCMD workshop download cache for
    /// Project Zomboid (the per-mod cached downloads, NOT the user's
    /// installed mods folder and NOT SteamCMD itself). Asks for
    /// confirmation first.
    /// </summary>
    private void ClearWorkshopCache_Click(object sender, RoutedEventArgs e)
    {
        var contentRoot = SteamCmdService.WorkshopContentRoot;

        if (!Directory.Exists(contentRoot))
        {
            AppendLog("Clear workshop cache: cache folder does not exist yet, nothing to do.");
            return;
        }

        List<string> entries;
        try
        {
            entries = Directory.GetDirectories(contentRoot).ToList();
        }
        catch (Exception ex)
        {
            AppendLog($"Could not list the workshop cache folder: {ex.Message}", "ERROR");
            MessageBox.Show($"Could not read the workshop cache folder:\n{ex.Message}");
            return;
        }

        if (entries.Count == 0)
        {
            AppendLog("Workshop cache is already empty.");
            return;
        }

        var confirm = MessageBox.Show(
            $"Delete the cached workshop download contents?\n\n" +
            $"Location: {contentRoot}\n" +
            $"{entries.Count} cached item(s).\n\n" +
            "SteamCMD itself and your installed mods folder are NOT affected.",
            "Clear Cached Workshop Mods", MessageBoxButton.YesNo, MessageBoxImage.Warning);
        if (confirm != MessageBoxResult.Yes)
        {
            AppendLog("Clear workshop cache: cancelled.");
            return;
        }

        int deleted = 0, failed = 0;
        long freed = 0;
        foreach (var dir in entries)
        {
            try
            {
                var size = GetDirectorySize(dir);
                Directory.Delete(dir, recursive: true);
                freed += size;
                deleted++;
            }
            catch
            {
                failed++;
            }
        }

        var summary = $"Workshop cache cleared: {deleted} item(s) deleted ({FormatSize(freed)} freed)" +
                      (failed > 0 ? $", {failed} item(s) skipped (files in use)" : "") + ".";
        AppendLog(summary, failed > 0 ? "WARNING" : "INFO");
        StatusText.Text = summary;
    }
```

