public static string GetContentPath(string workshopId) =>
    Path.Combine(SteamCmdDir, "steamapps", "workshop", "content", AppId, workshopId);

public static string WorkshopContentRootPath =>
    Path.Combine(SteamCmdDir, "steamapps", "workshop", "content", AppId);

/// <summary>
/// Deletes the SteamCMD workshop content cache that accumulates under
/// steamcmd\steamapps\workshop\content. SteamCMD itself (steamcmd.exe and
/// its client files, directly under steamcmd\) is left untouched.
/// Returns false when the cache cannot be deleted (e.g. a file is held
/// open by another process) rather than throwing.
/// </summary>
public static bool ClearWorkshopContentCache(Action<string> log)
{
    var contentRoot = Path.Combine(SteamCmdDir, "steamapps", "workshop", "content");
    if (!Directory.Exists(contentRoot))
    {
        log("No workshop content cache to clear.");
        return true;
    }

    try
    {
        long bytes = 0;
        foreach (var f in Directory.EnumerateFiles(contentRoot, "*", SearchOption.AllDirectories))
        {
            try { bytes += new FileInfo(f).Length; } catch { /* ignore inaccessible files */ }
        }

        Directory.Delete(contentRoot, recursive: true);
        log($"Workshop content cache cleared ({bytes / 1024.0 / 1024.0:0.##} MB) from {contentRoot}");
        return true;
    }
    catch (Exception ex)
    {
        log($"Could not delete the workshop content cache: {ex.Message}");
        return false;
    }
}

